static GemmConfig get_manual_config_asym(const GemmType& gemm_type, const KernelType& kernel_type,
                                  const int& m, const int& n, const int& k, const int& num_groups,
                                  const cute::UMMA::Major& major_a, const cute::UMMA::Major& major_b,
                                  const at::ScalarType& ab_dtype, const at::ScalarType& cd_dtype,
                                  const bool& with_accumulation, const int& num_sms,
                                  const int& block_m, const int& block_n, const int& block_k,
                                  const int& num_stages = 0) {
    DG_HOST_ASSERT(ab_dtype == torch::kFloat8_e4m3fn or ab_dtype == torch::kBFloat16);
    DG_HOST_ASSERT(cd_dtype == torch::kBFloat16 or cd_dtype == torch::kFloat);
    DG_HOST_ASSERT(block_m > 0 and block_n > 0 and block_k > 0);

    constexpr int fixed_num_stages = 2;
    if (num_stages > 0)
        DG_HOST_ASSERT(num_stages == fixed_num_stages);

    DG_HOST_ASSERT(ArchSpec::is_block_size_legal(kernel_type, major_a, major_b,
                                                 ab_dtype, cd_dtype, m, n, k,
                                                 block_m, block_n, block_k));
    DG_HOST_ASSERT(ArchSpec::is_num_stages_legal(ab_dtype, cd_dtype, fixed_num_stages,
                                                 block_m, block_n, block_k));

    // Decide the number of TMA multicasts and whether broadcast on A
    MulticastConfig multicast_config = {1, false};
    const auto& [is_legal_on_a, is_legal_on_b] = ArchSpec::get_multicast_legality(
        gemm_type, num_groups, m, n, block_m, block_n, num_sms);
    const bool is_legal[2] = {is_legal_on_b, is_legal_on_a};
    bool order[2] = {false, true};
    if (block_m > block_n)
        std::swap(order[0], order[1]);
    for (const bool& is_multicast_on_a: order) {
        if (m >= 512 and is_legal[static_cast<int>(is_multicast_on_a)]) {
            multicast_config = {2, is_multicast_on_a};
            break;
        }
    }

    constexpr int smem_capacity = ArchSpec::smem_capacity;
    const auto& smem_config = get_smem_config<ArchSpec>(gemm_type, kernel_type,
                                                        m, n, k,
                                                        block_m, block_n, block_k,
                                                        major_a, major_b,
                                                        ab_dtype, cd_dtype,
                                                        fixed_num_stages, multicast_config,
                                                        true);
    DG_HOST_ASSERT(smem_config.smem_size <= smem_capacity);

    // Some util functions
    // For asym grouped GEMMs (contiguous/masked), the CTA grid is
    // (ceil(n/block_n), num_groups) because each CTA sweeps M internally.
    const auto& get_num_blocks = [=](const int& bm, const int& bn) -> int {
        if (gemm_type == GemmType::MGroupedContiguous or gemm_type == GemmType::MGroupedMasked)
            return ceil_div(n, bn) * num_groups;
        return ceil_div(m, bm) * ceil_div(n, bn) * num_groups;
    };
    const auto& get_num_waves = [=](const int& bm, const int& bn) {
        return ceil_div(get_num_blocks(bm, bn), num_sms);
    };
    const int best_num_waves = get_num_waves(block_m, block_n);

    // Recompute the minimal number of SMs required
    int num_min_sms = num_sms;
    if (ArchSpec::should_minimize_num_sms()) {
        num_min_sms = ceil_div(get_num_blocks(block_m, block_n), best_num_waves);
        num_min_sms = align(num_min_sms, multicast_config.num_multicast);
        DG_HOST_ASSERT(num_min_sms <= num_sms);
    }

    const auto& config = GemmConfig {
        .gemm_type = gemm_type,
        .kernel_type = kernel_type,
        .ab_dtype = ab_dtype,
        .cd_dtype = cd_dtype,
        .major_a = major_a,
        .major_b = major_b,
        .with_accumulation = with_accumulation,
        .block_m = block_m,
        .block_n = block_n,
        .block_k = block_k,
        .num_stages = fixed_num_stages,
        .num_last_stages = ceil_div(k, block_k) % fixed_num_stages,

