                        b_desc.lo = advance_umma_desc_lo<kMajorB, LOAD_BLOCK_N, kSwizzleBMode, cutlass::bfloat16_t>(
                            b_desc_base_lo, 0, atom * DESC_ATOM_K + ki * UMMA_K);
                    } else {
