from __future__ import annotations

import os
from typing import Any

import torch

from .frozen_linear import (
    AsymExecutionStats,
    _GroupedPadding,
    _group_metadata_tensors,
    _normalize_bf16_output_dtype,
    _unpad_grouped_output,
)


CPU_LEFT_BF16_BINDING = "sm100_m_grouped_bf16_cpu_left_asym_gemm_nt_contiguous"
CPU_LEFT_BF16_PAIR_BINDING = "sm100_m_grouped_bf16_cpu_left_pair_asym_gemm_nt_contiguous"
CPU_LEFT_GROUPED_BLOCK_M = 128


def _env_positive_int(name: str, default: int) -> int:
    value = os.environ.get(name)
    if value is None or value == "":
        return int(default)
    try:
        parsed = int(value)
    except ValueError:
        return int(default)
    return parsed if parsed > 0 else int(default)


def _cpu_left_kernel_block_m() -> int:
    return _env_positive_int(
        "DG_BF16_CPU_LEFT_BLOCK_M",
        _env_positive_int("DG_BF16_BLOCK_M", 64),
    )


def _compact_grid_enabled() -> bool:
    return _env_positive_int("DG_BF16_CPU_LEFT_COMPACT_GRID", 0) != 0


def _binding_supports_compact_m_blocks(native: Any, min_argcount: int = 8) -> bool:
    code = getattr(native, "__code__", None)
    if code is None:
        return True
    return int(getattr(code, "co_argcount", 0)) >= int(min_argcount)


def _arch_major(device: torch.device) -> int | None:
    if device.type != "cuda" or not torch.cuda.is_available():
        return None
    return int(torch.cuda.get_device_capability(device)[0])


def cpu_left_grouped_bf16_reason(
    a_cpu: torch.Tensor,
    b_cuda: torch.Tensor,
    offsets: torch.Tensor,
    experts: torch.Tensor,
    *,
    output_dtype: torch.dtype | str = torch.bfloat16,
) -> str | None:
    """Return a named reason when the SM100 BF16 CPU-left path is unavailable."""

    if not torch.cuda.is_available():
        return "cuda_unavailable"
    if a_cpu.device.type != "cpu":
        return "input_not_cpu"
    if b_cuda.device.type != "cuda":
        return "weight_not_cuda"
    if _arch_major(b_cuda.device) != 10:
        return "requires_sm100"
    if a_cpu.dim() != 2 or b_cuda.dim() != 3:
        return "requires_2d_input_3d_weight"
    if a_cpu.dtype != torch.bfloat16 or b_cuda.dtype != torch.bfloat16:
        return "requires_bf16"
    try:
        _normalize_bf16_output_dtype(output_dtype)
    except ValueError:
        return "requires_bf16_or_fp32_output"
    if not a_cpu.is_pinned():
        return "input_not_pinned"
    if not a_cpu.is_contiguous() or not b_cuda.is_contiguous():
        return "requires_contiguous"
    if int(b_cuda.shape[0]) <= 0:
        return "requires_positive_groups"
    if int(a_cpu.shape[1]) != int(b_cuda.shape[2]):
        return "shape_mismatch"
    n = int(b_cuda.shape[1])
    k = int(b_cuda.shape[2])
    if n <= 0 or k <= 0:
        return "requires_positive_nk"
    if n % 8 != 0 or k % 8 != 0:
        return "requires_8_aligned_nk"
    if offsets.dim() != 1 or experts.dim() != 1 or experts.numel() < 2:
        return "metadata_mismatch"
    num_groups = int(experts.numel() - 1)
    if offsets.numel() != experts.numel() and offsets.numel() < 2 * num_groups:
        return "metadata_mismatch"

    import asym_gemm

    if not hasattr(asym_gemm, CPU_LEFT_BF16_BINDING):
        return "missing_sm100_cpu_left_bf16_binding"
    return None


def _pad_cpu_left_grouped_input_for_asym(
    x_cpu: torch.Tensor,
    offsets: torch.Tensor,
    experts: torch.Tensor,
    *,
    index_device: torch.device,
    block_m: int = CPU_LEFT_GROUPED_BLOCK_M,
) -> tuple[torch.Tensor, torch.Tensor, _GroupedPadding | None, int]:
    if offsets.numel() != experts.numel():
        return x_cpu, offsets, None, 0

    num_groups = int(experts.numel() - 1)
    # metadata (group starts/counts/padded offsets/index maps) depends only on
    # (offsets, block_m): memoize on the offsets tensor. The un-memoized version cost one
    # sync D2H + ~4 .item()s PER GROUP per call — a top backward hotspot under sTP.
    memo = getattr(offsets, "_asym_cpuleft_pad_memo", None)
    memo_key = (int(block_m), int(x_cpu.shape[0]), str(index_device))
    cached = None if memo is None else memo.get(memo_key)
    if cached is None:
        offsets_cpu = offsets.detach().to(device="cpu", dtype=torch.long)
        starts = offsets_cpu[:-1]
        counts = (offsets_cpu[1:] - starts).clamp_min(0)
        padded_counts = torch.div(counts + int(block_m) - 1, int(block_m), rounding_mode="floor") * int(block_m)
        kernel_block_m = _cpu_left_kernel_block_m()
        compact_m_blocks = int(
            torch.div(
                padded_counts.max() + int(kernel_block_m) - 1,
                int(kernel_block_m),
                rounding_mode="floor",
            ).item()
        ) if int(padded_counts.numel()) > 0 else 0
        padded_offsets_cpu = torch.cat(
            (
                torch.zeros(1, dtype=torch.long),
                torch.cumsum(padded_counts, dim=0),
            ),
            dim=0,
        )
        total_padded = int(padded_offsets_cpu[-1])
        copy_plan = []
        padded_row_chunks: list[torch.Tensor] = []
        original_row_chunks: list[torch.Tensor] = []
        if total_padded != int(x_cpu.shape[0]):
            for group in range(num_groups):
                rows = int(counts[group])
                if rows <= 0:
                    continue
                src_start = int(starts[group])
                dst_start = int(padded_offsets_cpu[group])
                copy_plan.append((dst_start, src_start, rows))
                padded_row_chunks.append(torch.arange(dst_start, dst_start + rows, dtype=torch.long))
                original_row_chunks.append(torch.arange(src_start, src_start + rows, dtype=torch.long))
        if padded_row_chunks:
            padded_rows = torch.cat(padded_row_chunks).to(device=index_device, non_blocking=True)
            original_rows = torch.cat(original_row_chunks).to(device=index_device, non_blocking=True)
        else:
            padded_rows = torch.empty((0,), device=index_device, dtype=torch.long)
            original_rows = torch.empty((0,), device=index_device, dtype=torch.long)
        padded_offsets_dev = padded_offsets_cpu.to(device=offsets.device, dtype=offsets.dtype, non_blocking=True)
        cached = (total_padded, compact_m_blocks, copy_plan, padded_rows, original_rows, padded_offsets_dev)
        if memo is None:
            memo = {}
            try:
                offsets._asym_cpuleft_pad_memo = memo  # type: ignore[attr-defined]
            except Exception:
                memo = None
        if memo is not None:
            memo[memo_key] = cached

    total_padded, compact_m_blocks, copy_plan, padded_rows, original_rows, padded_offsets_dev = cached
    if total_padded == int(x_cpu.shape[0]):
        return x_cpu, offsets, None, compact_m_blocks

    from .activation_offload import _alloc_cpu

    padded = _alloc_cpu((total_padded, int(x_cpu.shape[1])), x_cpu.dtype, pin_memory=True)
    padded.zero_()
    for dst_start, src_start, rows in copy_plan:
        padded[dst_start : dst_start + rows].copy_(x_cpu[src_start : src_start + rows])

    return (
        padded,
        padded_offsets_dev,
        _GroupedPadding(padded_rows=padded_rows, original_rows=original_rows),
        compact_m_blocks,
    )


def grouped_expert_lora_cpu_left(
    x_cpu: torch.Tensor,
    weight: torch.Tensor,
    offsets: torch.Tensor,
    experts: torch.Tensor,
    *,
    metadata: Any | None = None,
    compiled_dims: str = "nk",
    output_dtype: torch.dtype | str = torch.bfloat16,
    stats: AsymExecutionStats | None = None,
) -> torch.Tensor:
    """Run grouped LoRA-A as pinned CPU-left BF16 @ CUDA BF16.T on SM100."""

    if x_cpu.dim() != 2:
        raise RuntimeError("SM100 CPU-left grouped BF16 AsymGEMM is unavailable: requires_2d_input_3d_weight")
    if weight.dim() != 3:
        raise RuntimeError("SM100 CPU-left grouped BF16 AsymGEMM is unavailable: requires_2d_input_3d_weight")

    try:
        out_dtype = _normalize_bf16_output_dtype(output_dtype)
    except ValueError as exc:
        raise RuntimeError(
            "SM100 CPU-left grouped BF16 AsymGEMM is unavailable: requires_bf16_or_fp32_output"
        ) from exc
    m = int(x_cpu.shape[0])
    n = int(weight.shape[1])
    if m == 0:
        return torch.empty((0, n), device=weight.device, dtype=out_dtype)

    call_offsets = getattr(metadata, "offsets", offsets) if metadata is not None else offsets
    call_experts = getattr(metadata, "experts", experts) if metadata is not None else experts

    reason = cpu_left_grouped_bf16_reason(
        x_cpu,
        weight,
        call_offsets,
        call_experts,
        output_dtype=out_dtype,
    )
    if reason is not None:
        raise RuntimeError(f"SM100 CPU-left grouped BF16 AsymGEMM is unavailable: {reason}")

    import asym_gemm

    x_kernel, offsets_kernel, unpad, compact_m_blocks = _pad_cpu_left_grouped_input_for_asym(
        x_cpu,
        call_offsets,
        call_experts,
        index_device=weight.device,
    )
    out = torch.empty((int(x_kernel.shape[0]), n), device=weight.device, dtype=out_dtype)
    offsets_i32, experts_i32, list_size = _group_metadata_tensors(offsets_kernel, call_experts, device=weight.device)
    native = getattr(asym_gemm, CPU_LEFT_BF16_BINDING)
    if _compact_grid_enabled() and compact_m_blocks > 0 and _binding_supports_compact_m_blocks(native, min_argcount=8):
        native(
            x_kernel,
            weight,
            out,
            offsets_i32,
            experts_i32,
            list_size,
            compiled_dims,
            int(compact_m_blocks),
        )
    else:
        native(
            x_kernel,
            weight,
            out,
            offsets_i32,
            experts_i32,
            list_size,
            compiled_dims,
        )
    out = _unpad_grouped_output(out, unpad, output_m=m)
    if stats is not None:
        stats.cpu_left_lora_a_calls += 1
    return out


def grouped_expert_lora_pair_cpu_left(
    x_cpu: torch.Tensor,
    weight_gate: torch.Tensor,
    weight_up: torch.Tensor,
    offsets: torch.Tensor,
    experts: torch.Tensor,
    *,
    metadata: Any | None = None,
    compiled_dims: str = "nk",
    output_dtype: torch.dtype | str = torch.bfloat16,
    stats: AsymExecutionStats | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    out_dtype = _normalize_bf16_output_dtype(output_dtype)
    if weight_gate.shape != weight_up.shape:
        raise RuntimeError("SM100 CPU-left grouped BF16 pair AsymGEMM is unavailable: shape_mismatch")
    m = int(x_cpu.shape[0])
    n = int(weight_gate.shape[1])
    if m == 0:
        empty = torch.empty((0, n), device=weight_gate.device, dtype=out_dtype)
        return empty, torch.empty_like(empty)

    call_offsets = getattr(metadata, "offsets", offsets) if metadata is not None else offsets
    call_experts = getattr(metadata, "experts", experts) if metadata is not None else experts

from __future__ import annotations

from dataclasses import dataclass, field
import os
from typing import Any

import torch


_CPU_BUFFER_POOL: dict[tuple[torch.dtype, tuple[int, ...], bool], list[torch.Tensor]] = {}
_CPU_BUFFER_POOL_EVICTIONS = 0
_POOL_PIN_FALLBACK_CALLS = 0  # requested-pin allocs that fell back to pageable (process-wide)
_CPU_BUFFER_POOL_MAX_CACHED_BYTES = 0
_DEFAULT_CPU_POOL_MAX_BYTES = 32 * 1024**3

# actnvme governor (Stage 3): None unless ASYM_NVME_ROLES contains "activation" (rule 7).
# Bound at module bottom by get_act_spill_governor(); every hook below is inert while it is None.
_GOV = None


def _tensor_nbytes(tensor: torch.Tensor) -> int:
    return int(tensor.numel() * tensor.element_size())


def _cpu_pool_max_bytes() -> int:
    raw = os.environ.get("ASYM_EXPACT_CPU_POOL_MAX_BYTES")
    if raw is None or raw == "":
        return _DEFAULT_CPU_POOL_MAX_BYTES
    try:
        return max(0, int(raw))
    except ValueError:
        return _DEFAULT_CPU_POOL_MAX_BYTES


_DEFAULT_FG_ELEMENTWISE_CHUNK_MB = 1024  # probe-swept 2026-07-12: 1024 minimizes
# reserved (fragmentation gap 21→5 GiB @120k); 512 and 2048 are both worse.


def fg_elementwise_chunk_bytes() -> int:
    """Staging-buffer byte budget for row-chunked fg elementwise phases (silu/mul,
    silu backward, LoRA-B delta adds). 0 disables chunking (legacy full-width
    staging). Chunking trades nothing but launch count: same copied bytes, same
    FLOPs, but only chunk-sized HBM transients instead of full-width ones."""
    raw = os.environ.get(
        "ASYMM_FG_ELEMENTWISE_CHUNK_MB",
        os.environ.get("ASYM_GEMM_LF_CONFIG_ASYMM_FG_ELEMENTWISE_CHUNK_MB"),
    )
    if raw is None or str(raw).strip() == "":
        mb = _DEFAULT_FG_ELEMENTWISE_CHUNK_MB
    else:
        try:
            mb = int(str(raw).strip())
        except ValueError:
            mb = _DEFAULT_FG_ELEMENTWISE_CHUNK_MB
    return max(0, mb) * 1024 * 1024


def fg_chunk_rows(total_rows: int, row_width: int, element_size: int = 2) -> int:
    """Rows per chunk for fg elementwise chunking; 0 means do not chunk."""
    budget = fg_elementwise_chunk_bytes()
    if budget <= 0 or total_rows <= 0 or row_width <= 0:
        return 0
    rows = budget // max(1, row_width * element_size)
    if rows >= total_rows:
        return 0
    return max(8192, int(rows))


def _cpu_pool_cached_bytes() -> int:
    return sum(_tensor_nbytes(tensor) for tensors in _CPU_BUFFER_POOL.values() for tensor in tensors)


def _cpu_pool_shape_key(key: tuple[torch.dtype, tuple[int, ...], bool]) -> str:
    dtype, shape, pinned = key
    return f"{dtype}:{tuple(int(dim) for dim in shape)}:pinned={int(pinned)}"


def _trim_cpu_pool(max_cached_bytes: int) -> None:
    global _CPU_BUFFER_POOL_EVICTIONS
    while _cpu_pool_cached_bytes() > max_cached_bytes and _CPU_BUFFER_POOL:
        key = next(iter(_CPU_BUFFER_POOL))
        tensors = _CPU_BUFFER_POOL[key]
        if tensors:
            tensors.pop()
            _CPU_BUFFER_POOL_EVICTIONS += 1
        if not tensors:
            _CPU_BUFFER_POOL.pop(key, None)


def activation_offload_cpu_pool_stats() -> dict[str, Any]:
    cached_by_shape = {
        _cpu_pool_shape_key(key): sum(_tensor_nbytes(tensor) for tensor in tensors)
        for key, tensors in _CPU_BUFFER_POOL.items()
        if tensors
    }
    return {
        "cpu_pool_cached_bytes": _cpu_pool_cached_bytes(),
        "cpu_pool_cached_bytes_by_shape": cached_by_shape,
        "cpu_pool_num_cached_tensors": sum(len(tensors) for tensors in _CPU_BUFFER_POOL.values()),
        "cpu_pool_evictions": _CPU_BUFFER_POOL_EVICTIONS,
        # process-wide, same value on every row: max across rows, never sum
        "cpu_pool_pin_fallback_calls": _POOL_PIN_FALLBACK_CALLS,
        "cpu_pool_max_cached_bytes": _CPU_BUFFER_POOL_MAX_CACHED_BYTES,
        "cpu_pool_limit_bytes": _cpu_pool_max_bytes(),
    }


def clear_activation_offload_cpu_pool() -> None:
    global _CPU_BUFFER_POOL_EVICTIONS, _CPU_BUFFER_POOL_MAX_CACHED_BYTES
    _CPU_BUFFER_POOL.clear()
    _CPU_BUFFER_POOL_EVICTIONS = 0
    _CPU_BUFFER_POOL_MAX_CACHED_BYTES = 0


_POOL_ROW_BUCKET = 65536  # dim-0 bucket for >=2D buffers: variable routed-row counts (they
# differ per layer/branch/step under EP sharding) must collapse onto few reusable keys, or
# every allocation is a fresh cudaHostAlloc (measured: ~7 GB/layer of pinned allocs = 100s+
# of backward). Buffers are allocated at the bucketed size; callers receive an exact-shape
# dim-0 narrow (contiguous); _return_cpu recovers the base via `_asym_pool_base`.


def _alloc_cpu(shape: tuple[int, ...], dtype: torch.dtype, *, pin_memory: bool) -> torch.Tensor:
    pinned = bool(pin_memory and torch.cuda.is_available())
    shape = tuple(int(dim) for dim in shape)
    bucket_rows = 0
    if _GOV is None and len(shape) >= 2 and shape[0] > 0:
        granule = _POOL_ROW_BUCKET if shape[0] > _POOL_ROW_BUCKET else max(8192, 1)
        bucket_rows = ((shape[0] + granule - 1) // granule) * granule
    alloc_shape = (bucket_rows,) + shape[1:] if bucket_rows else shape
    key = (dtype, alloc_shape, pinned)

    def _narrow(base: torch.Tensor) -> torch.Tensor:
        if not bucket_rows or base.shape[0] == shape[0]:
            return base
        view = base.narrow(0, 0, shape[0])
        view._asym_pool_base = base  # type: ignore[attr-defined]
        return view

    pool = _CPU_BUFFER_POOL.get(key)
    if pool:
        tensor = pool.pop()
        if not pool:
            _CPU_BUFFER_POOL.pop(key, None)
        return _narrow(tensor)
    if _GOV is not None and pinned:
        # C8: aligned, padded pinned storage so io_ready() is True (spill-eligible); exact-shape view.
        return _GOV.alloc_cpu(key[1], dtype)
    try:
        return _narrow(torch.empty(alloc_shape, device="cpu", dtype=dtype, pin_memory=pinned))
    except RuntimeError:
        # Pinned alloc failed (host pinned-pool exhaustion): the pageable buffer keeps
        # the step alive but silently downgrades every later touch (blocking copies,
        # no ready events). Count it — same read rule as the saved-tensor modules'
        # pin_fallback counters: process-wide, max-across-rows, never sum.
        global _POOL_PIN_FALLBACK_CALLS
        if pinned:
            _POOL_PIN_FALLBACK_CALLS += 1
        return _narrow(torch.empty(alloc_shape, device="cpu", dtype=dtype))


def _return_cpu(tensor: torch.Tensor, *, pin_memory: bool) -> None:
    global _CPU_BUFFER_POOL_EVICTIONS, _CPU_BUFFER_POOL_MAX_CACHED_BYTES
    base = getattr(tensor, "_asym_pool_base", None)
    if base is not None:
        tensor = base  # return the full bucketed buffer, keyed by its own shape
    if tensor.device.type != "cpu" or not tensor.is_contiguous():
        return
    pinned = bool(pin_memory and torch.cuda.is_available() and tensor.is_pinned())
    key = (tensor.dtype, tuple(int(dim) for dim in tensor.shape), pinned)
    returned = tensor.detach()
    nbytes = _tensor_nbytes(returned)
    max_cached_bytes = _cpu_pool_max_bytes()
    if nbytes > max_cached_bytes:
        _CPU_BUFFER_POOL_EVICTIONS += 1
        return
    _trim_cpu_pool(max_cached_bytes - nbytes)
    _CPU_BUFFER_POOL.setdefault(key, []).append(returned)
    _CPU_BUFFER_POOL_MAX_CACHED_BYTES = max(_CPU_BUFFER_POOL_MAX_CACHED_BYTES, _cpu_pool_cached_bytes())


@dataclass(frozen=True)
class CPUActivationHandle:
    tag: str
    tensor: torch.Tensor
    original_device: torch.device
    original_dtype: torch.dtype
    original_shape: tuple[int, ...]

    @property
    def nbytes(self) -> int:
        return _tensor_nbytes(self.tensor)


@dataclass
class ActivationOffloadStats:
    offloaded_bytes: int = 0
    cpu_owned_bytes: int = 0
    cpu_peak_bytes_live: int = 0
    staged_bytes: int = 0
    max_stage_bytes_live: int = 0
    num_offloads: int = 0
    num_cpu_allocs: int = 0
    num_stages: int = 0
    offload_bytes_by_tag: dict[str, int] = field(default_factory=dict)
    cpu_bytes_by_tag: dict[str, int] = field(default_factory=dict)
    cpu_peak_by_tag: dict[str, int] = field(default_factory=dict)
    stage_bytes_by_tag: dict[str, int] = field(default_factory=dict)
    stage_peak_by_tag: dict[str, int] = field(default_factory=dict)

    def as_dict(self) -> dict[str, Any]:
        pool_stats = activation_offload_cpu_pool_stats()
        return {
            "offloaded_bytes": self.offloaded_bytes,
            "cpu_owned_bytes": self.cpu_owned_bytes,
            "cpu_live_bytes": self.cpu_owned_bytes,
            "cpu_peak_bytes_live": self.cpu_peak_bytes_live,
            "staged_bytes": self.staged_bytes,
            "max_stage_bytes_live": self.max_stage_bytes_live,
            "num_offloads": self.num_offloads,
            "num_cpu_allocs": self.num_cpu_allocs,
            "num_stages": self.num_stages,
            "offload_bytes_by_tag": dict(self.offload_bytes_by_tag),
            "cpu_bytes_by_tag": dict(self.cpu_bytes_by_tag),
            "cpu_peak_by_tag": dict(self.cpu_peak_by_tag),
            "stage_bytes_by_tag": dict(self.stage_bytes_by_tag),
            "stage_peak_by_tag": dict(self.stage_peak_by_tag),
            **pool_stats,
        }


